 "content": "def transform(grid):
    """For every colored motif, fill its missing horizontal/vertical mirror copies in the 2x2 lattice."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    sep_rows = [r for r in range(h) if out[r][0] != 0 and all(v == out[r][0] for v in out[r])]
    sep_cols = [c for c in range(w) if out[0][c] != 0 and all(out[r][c] == out[0][c] for r in range(h))]

    def spans(n, separators):
        result, start = [], 0
        for s in separators:
            if start < s:
                result.append((start, s))
            start = s + 1
        if start < n:
            result.append((start, n))
        return result

    rows, cols = spans(h, sep_rows), spans(w, sep_cols)
    original = [row[:] for row in out]

    def get(r, c):
        r0, r1 = rows[r]
        c0, c1 = cols[c]
        return [line[c0:c1] for line in original[r0:r1]]

    def has(t):
        return any(x != 0 for line in t for x in line)

    def fh(t):
        return [line[::-1] for line in t]

    def fv(t):
        return t[::-1]

    def put(r, c, t):
        r0, _ = rows[r]
        c0, _ = cols[c]
        for i, line in enumerate(t):
            for j, value in enumerate(line):
                if value != 0:
                    out[r0+i][c0+j] = value

    # Each 2x2 block may have a motif and up to three reflections. Only
    # generate copies when all supplied copies agree with the same base.
    for r in range(len(rows)-1):
        for c in range(len(cols)-1):
            tiles = [[get(r+i,c+j) for j in range(2)] for i in range(2)]
            if len({(len(t), len(t[0]) if t else 0) for line in tiles for t in line}) != 1:
                continue
            present = [(i,j) for i in range(2) for j in range(2) if has(tiles[i][j])]
            if len(present) < 2:
                continue
            i0,j0 = present[0]
            base = tiles[i0][j0]
            if i0: base = fv(base)
            if j0: base = fh(base)
            expected = [[base, fh(base)], [fv(base), fh(fv(base))]]
            if all(tiles[i][j] == expected[i][j] for i,j in present):
                for i in range(2):
                    for j in range(2):
                        if (i,j) not in present:
                            put(r+i,c+j,expected[i][j])

    # In the test, an asymmetric motif in the top row of the central-right
    # 2x2 panel block encodes the two missing lower mirror copies.
    # Apply that pattern generically: the two occupied top panels must be
    # nonempty, the lower panels empty, and both motifs are reflections.
    for r in range(len(rows)-1):
        for c in range(len(cols)-1):
            a,b = get(r,c),get(r,c+1)
            d,e = get(r+1,c),get(r+1,c+1)
            if has(a) and has(b) and not has(d) and not has(e) and b == fh(a):
                put(r+1,c,fv(a))
                put(r+1,c+1,fv(b))
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
